body.query:
query TaxonChildren($limit: Int, $offset: Int, $datasetKey: ID, $key: ID!) {
  taxon(datasetKey: $datasetKey, key: $key) {
    children(limit: $limit, offset: $offset) {
      count
      endOfRecords
      limit
      offset
      results {
        taxonID
        label: scientificName
        rank: taxonRank
        status: taxonomicStatus
        childrenCount: children
      }
    }
  }
}
